 */
public object FfiConverterTypeWalletUnlock: FfiConverter<WalletUnlock, Pointer> {

    override fun lower(value: WalletUnlock): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): WalletUnlock {
        return WalletUnlock(value)
    }

    override fun read(buf: ByteBuffer): WalletUnlock {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: WalletUnlock) = 8UL

    override fun write(value: WalletUnlock, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



