/**
 * What a decrypted payload turned out to be (`Opened` in the desktop client, flattened for Kotlin).
 */
sealed class Decrypted {
    
    /**
     * Ciphertext, opened with one of the keys we were given.
     */
    data class Text(
        val v1: kotlin.String) : Decrypted() {
        companion object
    }
    
    /**
     * Ciphertext none of the keys opens (the room's key isn't on this device yet).
     */
    object Locked : Decrypted()
    
    
    /**
     * Not sealed at all — public rooms and old messages.
     */
    data class Plain(
        val v1: kotlin.String) : Decrypted() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDecrypted : FfiConverterRustBuffer<Decrypted>{
    override fun read(buf: ByteBuffer): Decrypted {
        return when(buf.getInt()) {
            1 -> Decrypted.Text(
                FfiConverterString.read(buf),
                )
            2 -> Decrypted.Locked
            3 -> Decrypted.Plain(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Decrypted) = when(value) {
        is Decrypted.Text -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
        is Decrypted.Locked -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Decrypted.Plain -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: Decrypted, buf: ByteBuffer) {
        when(value) {
            is Decrypted.Text -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is Decrypted.Locked -> {
                buf.putInt(2)
                Unit
            }
            is Decrypted.Plain -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
