 * reached (no network, wrong address, TLS).
 */
sealed class MobileException: kotlin.Exception() {
    
    class Api(
        
        val `status`: kotlin.UShort?, 
        
        val `detail`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "status=${ `status` }, detail=${ `detail` }"
    }
    
    class SealFailed(
        ) : MobileException() {
        override val message
            get() = ""
    }
    
    class Json(
        
        val `detail`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Store(
        
        val `detail`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Wallet(
        
        val `detail`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * A sealed room whose key isn't available here (the sentence is shown to the user).
     */
    class Keys(
        
        val `detail`: kotlin.String
        ) : MobileException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<MobileException> {
        override fun lift(error_buf: RustBuffer.ByValue): MobileException = FfiConverterTypeMobileError.lift(error_buf)
    }

    
}

